import { formatNumber, t } from "./i18n.js";
import { renderServerBlockHtml } from "./rendered-html-sanitizer.js";

export const accordionLimits = {
  titleLength: 120,
  items: 50,
  itemTitleLength: 300,
  itemContentLength: 8000,
  idLength: 64
};

function createId(prefix) {
  const random = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}-${random}`.slice(0, accordionLimits.idLength);
}

function recordValue(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : null;
}

function stringValue(value, fallback, maxLength) {
  return (typeof value === "string" ? value : fallback).slice(0, maxLength);
}

function safeId(value, fallback) {
  const id = typeof value === "string" ? value.trim().slice(0, accordionLimits.idLength) : "";
  return id || fallback;
}

function uniqueId(requested, seen, fallbackPrefix) {
  let id = requested;
  let attempt = 1;
  while (seen.has(id)) {
    id = `${fallbackPrefix}-${attempt}`.slice(0, accordionLimits.idLength);
    attempt += 1;
  }
  seen.add(id);
  return id;
}

function normalizeIcon(value) {
  return typeof value === "string" && value.trim() ? value : "📄";
}

export function createDefaultAccordionData() {
  return {
    title: t("accordion.defaultTitle"),
    showOrder: false,
    items: [
      {
        id: createId("accordion-item"),
        icon: "📄",
        title: t("accordion.defaultItemTitle", { number: formatNumber(1) }),
        content: "",
        open: true
      }
    ]
  };
}

export function normalizeAccordionData(value) {
  const source = recordValue(value) ?? {};
  const fallback = createDefaultAccordionData();
  const itemSources = Array.isArray(source.items) ? source.items.slice(0, accordionLimits.items) : fallback.items;
  const seen = new Set();
  const items = itemSources
    .map(recordValue)
    .filter(Boolean)
    .map((item, index) => ({
      id: uniqueId(safeId(item.id, createId("accordion-item")), seen, `accordion-item-${index + 1}`),
      icon: normalizeIcon(item.icon),
      title: stringValue(
        item.title,
        t("accordion.defaultItemTitle", { number: formatNumber(index + 1) }),
        accordionLimits.itemTitleLength
      ),
      content: stringValue(item.content, "", accordionLimits.itemContentLength),
      open: item.open !== false
    }));

  return {
    title: stringValue(source.title, fallback.title, accordionLimits.titleLength),
    showOrder: source.showOrder === true,
    items
  };
}

function resizeTextarea(textarea) {
  textarea.style.height = "auto";
  textarea.style.height = `${Math.max(textarea.scrollHeight, 72)}px`;
}

function renderFallbackPreview(preview, data, renderIcon) {
  preview.replaceChildren();
  const section = document.createElement("section");
  section.className = "rendered-accordion";
  const title = document.createElement("div");
  title.className = "rendered-accordion-title";
  title.textContent = data.title || t("accordion.defaultTitle");
  section.append(title);

  data.items.forEach((item, index) => {
    const details = document.createElement("details");
    details.className = "rendered-accordion-item";
    details.open = item.open;
    const summary = document.createElement("summary");
    summary.className = "rendered-accordion-summary";
    if (data.showOrder) {
      const order = document.createElement("span");
      order.className = "rendered-accordion-order";
      order.textContent = formatNumber(index + 1);
      summary.append(order);
    }
    const icon = document.createElement("span");
    icon.className = "rendered-accordion-item-icon";
    icon.dataset.iconValue = item.icon;
    if (renderIcon) renderIcon(icon, item.icon, "📄");
    else icon.textContent = item.icon;
    const label = document.createElement("span");
    label.className = "rendered-accordion-item-title";
    label.textContent = item.title || t("accordion.defaultItemTitle", { number: formatNumber(index + 1) });
    const content = document.createElement("div");
    content.className = "rendered-accordion-content";
    content.textContent = item.content;
    summary.append(icon, label);
    details.append(summary, content);
    section.append(details);
  });
  preview.append(section);
}

function focusAccordionControl(editor, itemId, selector = ".accordion-item-title-input") {
  requestAnimationFrame(() => {
    const item = editor.querySelector(`[data-accordion-item-id="${CSS.escape(itemId)}"]`);
    item?.querySelector(selector)?.focus();
  });
}

export function createAccordionEditor(row, value, options = {}) {
  const { onDirty, renderIcon, onPickIcon, previewHtml = "" } = options;
  const data = normalizeAccordionData(value);
  const editor = document.createElement("div");
  editor.className = "accordion-block-editor";
  editor.accordionData = data;
  editor.classList.toggle("show-order", data.showOrder);
  const isReadOnly = () => row?.getAttribute("aria-readonly") === "true" || row?.classList.contains("is-read-only");

  const editSurface = document.createElement("div");
  editSurface.className = "accordion-edit-surface";

  const heading = document.createElement("div");
  heading.className = "accordion-block-heading";
  const titleInput = document.createElement("input");
  titleInput.type = "text";
  titleInput.className = "accordion-title-input";
  titleInput.maxLength = accordionLimits.titleLength;
  titleInput.value = data.title;
  titleInput.placeholder = t("accordion.titlePlaceholder");
  titleInput.setAttribute("aria-label", t("accordion.titleAria"));
  const addButton = document.createElement("button");
  addButton.type = "button";
  addButton.className = "accordion-add-item";
  addButton.dataset.action = "accordion-add-item";
  addButton.disabled = data.items.length >= accordionLimits.items;
  addButton.textContent = `＋ ${t("accordion.addItem")}`;
  addButton.setAttribute("aria-label", t("accordion.addItem"));
  heading.append(titleInput, addButton);

  const list = document.createElement("div");
  list.className = "accordion-items";
  list.setAttribute("role", "list");

  data.items.forEach((item, index) => {
    const itemElement = document.createElement("article");
    itemElement.className = "accordion-item";
    itemElement.dataset.accordionItemId = item.id;
    itemElement.setAttribute("role", "listitem");

    const header = document.createElement("div");
    header.className = "accordion-item-header";

    const dragHandle = document.createElement("button");
    dragHandle.type = "button";
    dragHandle.className = "accordion-item-drag-handle";
    dragHandle.draggable = true;
    dragHandle.dataset.accordionItemId = item.id;
    dragHandle.textContent = "⠿";
    dragHandle.title = t("accordion.dragItem");
    dragHandle.setAttribute("aria-label", t("accordion.dragItem"));

    const order = document.createElement("span");
    order.className = "accordion-item-order";
    order.textContent = formatNumber(index + 1);
    order.setAttribute("aria-hidden", "true");

    const iconButton = document.createElement("button");
    iconButton.type = "button";
    iconButton.className = "accordion-item-icon-button";
    iconButton.dataset.action = "accordion-pick-icon";
    iconButton.dataset.accordionItemId = item.id;
    iconButton.title = t("accordion.changeIcon");
    iconButton.setAttribute("aria-label", t("accordion.changeIconFor", { title: item.title || formatNumber(index + 1) }));
    if (renderIcon) renderIcon(iconButton, item.icon, "📄");
    else iconButton.textContent = item.icon;

    const disclosure = document.createElement("button");
    disclosure.type = "button";
    disclosure.className = "accordion-item-toggle";
    disclosure.dataset.action = "accordion-toggle-item";
    disclosure.dataset.accordionItemId = item.id;
    disclosure.setAttribute("aria-expanded", String(item.open));
    disclosure.setAttribute("aria-controls", `accordion-panel-${item.id}`);
    disclosure.title = t(item.open ? "accordion.collapseItem" : "accordion.expandItem");
    const chevron = document.createElement("span");
    chevron.className = "accordion-item-chevron";
    chevron.setAttribute("aria-hidden", "true");
    chevron.textContent = item.open ? "⌄" : "›";
    disclosure.append(chevron);

    const itemTitle = document.createElement("input");
    itemTitle.type = "text";
    itemTitle.className = "accordion-item-title-input";
    itemTitle.maxLength = accordionLimits.itemTitleLength;
    itemTitle.value = item.title;
    itemTitle.placeholder = t("accordion.itemTitlePlaceholder");
    itemTitle.setAttribute("aria-label", t("accordion.itemTitleAria", { number: formatNumber(index + 1) }));
    itemTitle.dataset.accordionItemId = item.id;

    const controls = document.createElement("div");
    controls.className = "accordion-item-actions";
    const moveUp = document.createElement("button");
    moveUp.type = "button";
    moveUp.dataset.action = "accordion-move-up";
    moveUp.dataset.accordionItemId = item.id;
    moveUp.className = "accordion-item-action";
    moveUp.textContent = "↑";
    moveUp.title = t("accordion.moveUp");
    moveUp.setAttribute("aria-label", t("accordion.moveUp"));
    moveUp.disabled = index === 0;
    const moveDown = document.createElement("button");
    moveDown.type = "button";
    moveDown.dataset.action = "accordion-move-down";
    moveDown.dataset.accordionItemId = item.id;
    moveDown.className = "accordion-item-action";
    moveDown.textContent = "↓";
    moveDown.title = t("accordion.moveDown");
    moveDown.setAttribute("aria-label", t("accordion.moveDown"));
    moveDown.disabled = index === data.items.length - 1;
    const remove = document.createElement("button");
    remove.type = "button";
    remove.dataset.action = "accordion-remove-item";
    remove.dataset.accordionItemId = item.id;
    remove.className = "accordion-item-action accordion-item-remove";
    remove.textContent = "⌫";
    remove.title = t("accordion.removeItem");
    remove.setAttribute("aria-label", t("accordion.removeItem"));
    controls.append(moveUp, moveDown, remove);

    header.append(dragHandle, order, iconButton, disclosure, itemTitle, controls);

    const panel = document.createElement("div");
    panel.id = `accordion-panel-${item.id}`;
    panel.className = "accordion-item-panel";
    panel.hidden = !item.open;
    const content = document.createElement("textarea");
    content.className = "accordion-item-content";
    content.rows = 3;
    content.maxLength = accordionLimits.itemContentLength;
    content.value = item.content;
    content.placeholder = t("accordion.contentPlaceholder");
    content.setAttribute("aria-label", t("accordion.contentAria", { title: item.title || formatNumber(index + 1) }));
    content.dataset.accordionItemId = item.id;
    panel.append(content);
    itemElement.append(header, panel);
    list.append(itemElement);
    requestAnimationFrame(() => resizeTextarea(content));
  });

  const empty = document.createElement("div");
  empty.className = "accordion-empty-state";
  empty.hidden = data.items.length > 0;
  empty.textContent = t("accordion.emptyState");

  editSurface.append(heading, list, empty);

  const preview = document.createElement("div");
  preview.className = "block-rendered-preview accordion-block-preview";
  if (previewHtml) renderServerBlockHtml(preview, previewHtml);
  else renderFallbackPreview(preview, data, renderIcon);

  editor.append(editSurface, preview);

  const syncAccordionItemControls = () => {
    addButton.disabled = data.items.length >= accordionLimits.items;
    empty.hidden = data.items.length > 0;
    data.items.forEach((item, index) => {
      const itemElement = list.querySelector(`.accordion-item[data-accordion-item-id="${CSS.escape(item.id)}"]`);
      if (!itemElement) return;
      const order = itemElement.querySelector(".accordion-item-order");
      if (order) order.textContent = formatNumber(index + 1);
      const itemTitle = itemElement.querySelector(".accordion-item-title-input");
      if (itemTitle) itemTitle.setAttribute("aria-label", t("accordion.itemTitleAria", { number: formatNumber(index + 1) }));
      const accessibleTitle = item.title || formatNumber(index + 1);
      const iconButton = itemElement.querySelector('[data-action="accordion-pick-icon"]');
      if (iconButton) iconButton.setAttribute("aria-label", t("accordion.changeIconFor", { title: accessibleTitle }));
      const content = itemElement.querySelector(".accordion-item-content");
      if (content) content.setAttribute("aria-label", t("accordion.contentAria", { title: accessibleTitle }));
      const moveUp = itemElement.querySelector('[data-action="accordion-move-up"]');
      if (moveUp) moveUp.disabled = index === 0;
      const moveDown = itemElement.querySelector('[data-action="accordion-move-down"]');
      if (moveDown) moveDown.disabled = index === data.items.length - 1;
    });
    editor.accordionData = data;
  };

  const focusWithoutScroll = (target) => {
    if (!target) return;
    try {
      target.focus({ preventScroll: true });
    } catch {
      target.focus();
    }
  };

  const replaceEditor = ({ focusItemId = null, focusSelector } = {}) => {
    const replacement = createAccordionEditor(row, data, {
      onDirty,
      renderIcon,
      onPickIcon,
      previewHtml: ""
    });
    editor.replaceWith(replacement);
    onDirty?.();
    if (focusItemId) focusAccordionControl(replacement, focusItemId, focusSelector);
    return replacement;
  };

  editor.addEventListener("input", (event) => {
    if (isReadOnly()) return;
    if (event.target === titleInput) {
      data.title = titleInput.value.slice(0, accordionLimits.titleLength);
      editor.accordionData = data;
      onDirty?.();
      return;
    }
    const itemId = event.target?.dataset?.accordionItemId;
    if (!itemId) return;
    const item = data.items.find((candidate) => candidate.id === itemId);
    if (!item) return;
    if (event.target.classList.contains("accordion-item-title-input")) {
      item.title = event.target.value.slice(0, accordionLimits.itemTitleLength);
    } else if (event.target.classList.contains("accordion-item-content")) {
      item.content = event.target.value.slice(0, accordionLimits.itemContentLength);
      resizeTextarea(event.target);
    } else {
      return;
    }
    editor.accordionData = data;
    onDirty?.();
  });

  editor.addEventListener("click", (event) => {
    if (isReadOnly()) return;
    const button = event.target.closest("button[data-action]");
    if (!button || !editor.contains(button)) return;
    const action = button.dataset.action;
    const itemId = button.dataset.accordionItemId;
    const itemIndex = data.items.findIndex((candidate) => candidate.id === itemId);

    if (action === "accordion-add-item") {
      if (data.items.length >= accordionLimits.items) return;
      const nextIndex = data.items.length + 1;
      const item = {
        id: createId("accordion-item"),
        icon: "📄",
        title: t("accordion.defaultItemTitle", { number: formatNumber(nextIndex) }),
        content: "",
        open: true
      };
      data.items.push(item);
      replaceEditor({ focusItemId: item.id });
      return;
    }
    if (itemIndex < 0) return;
    const item = data.items[itemIndex];

    if (action === "accordion-toggle-item") {
      item.open = !item.open;
      button.setAttribute("aria-expanded", String(item.open));
      button.title = t(item.open ? "accordion.collapseItem" : "accordion.expandItem");
      button.querySelector(".accordion-item-chevron").textContent = item.open ? "⌄" : "›";
      const panel = editor.querySelector(`#accordion-panel-${CSS.escape(item.id)}`);
      if (panel) panel.hidden = !item.open;
      editor.accordionData = data;
      onDirty?.();
      return;
    }
    if (action === "accordion-pick-icon") {
      onPickIcon?.({ itemId: item.id, icon: item.icon, trigger: button });
      return;
    }
    if (action === "accordion-remove-item") {
      const itemElement = button.closest(".accordion-item");
      data.items.splice(itemIndex, 1);
      const focusItemId = data.items[Math.min(itemIndex, data.items.length - 1)]?.id ?? null;
      const focusTarget = focusItemId
        ? list.querySelector(`.accordion-item[data-accordion-item-id="${CSS.escape(focusItemId)}"] .accordion-item-title-input`)
        : addButton;

      // Keep the live editor mounted. Replacing the entire editor here briefly
      // removes focus and resets every textarea before focus/height restoration
      // on the next animation frame, which is visible as a block flicker.
      focusWithoutScroll(focusTarget);
      itemElement?.remove();
      syncAccordionItemControls();
      renderFallbackPreview(preview, data, renderIcon);
      onDirty?.();
      return;
    }
    if (action === "accordion-move-up" && itemIndex > 0) {
      [data.items[itemIndex - 1], data.items[itemIndex]] = [data.items[itemIndex], data.items[itemIndex - 1]];
      replaceEditor({ focusItemId: item.id, focusSelector: '[data-action="accordion-move-up"]' });
      return;
    }
    if (action === "accordion-move-down" && itemIndex < data.items.length - 1) {
      [data.items[itemIndex], data.items[itemIndex + 1]] = [data.items[itemIndex + 1], data.items[itemIndex]];
      replaceEditor({ focusItemId: item.id, focusSelector: '[data-action="accordion-move-down"]' });
    }
  });

  let draggedId = null;
  const clearDropIndicators = () => {
    for (const item of list.querySelectorAll(".accordion-item")) item.classList.remove("drop-before", "drop-after", "is-dragging");
  };

  list.addEventListener("dragstart", (event) => {
    if (isReadOnly()) {
      event.preventDefault();
      return;
    }
    const handle = event.target.closest(".accordion-item-drag-handle");
    if (!handle || !list.contains(handle)) return;
    draggedId = handle.dataset.accordionItemId;
    if (!draggedId) return;
    event.dataTransfer?.setData("text/plain", draggedId);
    if (event.dataTransfer) event.dataTransfer.effectAllowed = "move";
    handle.closest(".accordion-item")?.classList.add("is-dragging");
  });

  list.addEventListener("dragover", (event) => {
    if (!draggedId) return;
    if (isReadOnly()) {
      clearDropIndicators();
      draggedId = null;
      return;
    }
    const target = event.target.closest(".accordion-item");
    if (!target || target.dataset.accordionItemId === draggedId) return;
    event.preventDefault();
    clearDropIndicators();
    const rect = target.getBoundingClientRect();
    target.classList.add(event.clientY >= rect.top + rect.height / 2 ? "drop-after" : "drop-before");
    if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
  });

  list.addEventListener("drop", (event) => {
    if (!draggedId) return;
    if (isReadOnly()) {
      event.preventDefault();
      clearDropIndicators();
      draggedId = null;
      return;
    }
    const target = event.target.closest(".accordion-item");
    if (!target || target.dataset.accordionItemId === draggedId) {
      clearDropIndicators();
      draggedId = null;
      return;
    }
    event.preventDefault();
    const sourceIndex = data.items.findIndex((item) => item.id === draggedId);
    const targetIndex = data.items.findIndex((item) => item.id === target.dataset.accordionItemId);
    if (sourceIndex < 0 || targetIndex < 0) return;
    const targetRect = target.getBoundingClientRect();
    const after = event.clientY >= targetRect.top + targetRect.height / 2;
    const [moved] = data.items.splice(sourceIndex, 1);
    let insertionIndex = data.items.findIndex((item) => item.id === target.dataset.accordionItemId);
    if (after) insertionIndex += 1;
    data.items.splice(Math.max(0, insertionIndex), 0, moved);
    clearDropIndicators();
    const focusItemId = draggedId;
    draggedId = null;
    replaceEditor({ focusItemId, focusSelector: ".accordion-item-drag-handle" });
  });

  list.addEventListener("dragend", () => {
    draggedId = null;
    clearDropIndicators();
  });

  return editor;
}

export function extractAccordionData(row) {
  return normalizeAccordionData(row?.querySelector(".accordion-block-editor")?.accordionData);
}

function normalizeEditorAccordionDataInPlace(editor) {
  const current = recordValue(editor?.accordionData);
  if (!current) return null;
  const normalized = normalizeAccordionData(current);

  // createAccordionEditor keeps `data` in its event-handler closure. External
  // controls (icon picker / block menu) must therefore preserve that root
  // object identity instead of replacing editor.accordionData with a clone.
  current.title = normalized.title;
  current.showOrder = normalized.showOrder;
  current.items = normalized.items;
  editor.accordionData = current;
  return current;
}

export function setAccordionShowOrder(row, showOrder) {
  const editor = row?.querySelector(".accordion-block-editor");
  if (!editor) return false;
  const data = normalizeEditorAccordionDataInPlace(editor);
  if (!data) return false;
  data.showOrder = showOrder === true;
  editor.accordionData = data;
  editor.classList.toggle("show-order", data.showOrder);
  return true;
}

export function setAccordionItemIcon(row, itemId, icon, renderIcon) {
  const editor = row?.querySelector(".accordion-block-editor");
  if (!editor || !itemId) return false;
  const data = normalizeEditorAccordionDataInPlace(editor);
  if (!data) return false;
  const item = data.items.find((candidate) => candidate.id === itemId);
  if (!item) return false;
  item.icon = normalizeIcon(icon);
  editor.accordionData = data;
  const button = editor.querySelector(`[data-action="accordion-pick-icon"][data-accordion-item-id="${CSS.escape(itemId)}"]`);
  if (button) {
    if (renderIcon) renderIcon(button, item.icon, "📄");
    else button.textContent = item.icon;
  }
  return true;
}

export function summarizeAccordionData(value) {
  const accordion = normalizeAccordionData(value);
  return [accordion.title, ...accordion.items.flatMap((item) => [item.title, item.content])]
    .filter(Boolean)
    .join("\n")
    .slice(0, 20000);
}

public/database-block.js.source:
import { formatNumber, t } from "./i18n.js";

export const databaseLimits = {
  titleLength: 120,
  properties: 20,
  propertyNameLength: 80,
  rows: 200,
  views: 12,
  viewNameLength: 80,
  optionsPerProperty: 30,
  optionNameLength: 80,
  filtersPerView: 8,
  sortsPerView: 8,
  textLength: 2000,
  urlLength: 2000,
  idLength: 64
};

export const databasePropertyTypes = ["title", "text", "number", "select", "multi_select", "checkbox", "date", "url"];
export const databaseViewTypes = ["table", "board", "list"];
const databaseOptionColors = ["gray", "blue", "purple", "green", "yellow", "red", "pink", "orange"];
const databaseFilterOperators = ["contains", "equals", "is_empty", "is_not_empty", "checked", "unchecked"];
const unsafeDatabaseIds = new Set(["__proto__", "constructor", "prototype"]);
const databaseToolbarPanels = [
  { selector: ".database-properties-panel", reopenKey: "openProperties" },
  { selector: ".database-filter-panel", reopenKey: "openFilters" },
  { selector: ".database-sort-panel", reopenKey: "openSorts" },
  { selector: ".database-view-options-panel", reopenKey: "openViewOptions" },
  { selector: ".database-search-panel" },
  { selector: ".database-new-menu" }
];
const openDatabaseToolbarPanelSelector = databaseToolbarPanels
  .map(({ selector }) => `${selector}[open]`)
  .join(",");
// Outside pointer interaction can blur a property field whose change handler
// rebuilds the editor. Keep the dismissal authoritative across that rebuild.
const databaseToolbarLightDismissSuppressions = new WeakMap();

function closestMatchingElement(target, selector) {
  return target && typeof target.closest === "function" ? target.closest(selector) : null;
}

function databaseToolbarPanelEntry(panel) {
  return databaseToolbarPanels.find(({ selector }) => panel?.matches?.(selector)) ?? null;
}

function markDatabaseToolbarLightDismiss(panel) {
  const row = panel?.closest?.(".editor-block-row");
  const entry = databaseToolbarPanelEntry(panel);
  if (!row || !entry?.reopenKey) return;
  const suppressions = databaseToolbarLightDismissSuppressions.get(row) ?? new Set();
  suppressions.add(entry.reopenKey);
  databaseToolbarLightDismissSuppressions.set(row, suppressions);
  setTimeout(() => {
    const current = databaseToolbarLightDismissSuppressions.get(row);
    if (!current) return;
    current.delete(entry.reopenKey);
    if (!current.size) databaseToolbarLightDismissSuppressions.delete(row);
  }, 0);
}

function consumeDatabaseToolbarLightDismiss(row, reopenKey) {
  const suppressions = databaseToolbarLightDismissSuppressions.get(row);
  if (!suppressions?.delete(reopenKey)) return false;
  if (!suppressions.size) databaseToolbarLightDismissSuppressions.delete(row);
  return true;
}

export function dismissDatabaseToolbarPopovers(root, eventTarget = null) {
  if (!root || typeof root.querySelectorAll !== "function") return false;
  const containingOpenPanel = closestMatchingElement(eventTarget, openDatabaseToolbarPanelSelector);
  let dismissed = false;
  root.querySelectorAll(openDatabaseToolbarPanelSelector).forEach((panel) => {
    if (panel === containingOpenPanel) return;
    markDatabaseToolbarLightDismiss(panel);
    panel.removeAttribute("open");
    dismissed = true;
  });
  return dismissed;
}

function createId(prefix) {
  const random = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}-${random}`.slice(0, databaseLimits.idLength);
}

function recordValue(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : null;
}

function collectRecordValues(value, limit, recoverableKeys) {
  if (!Array.isArray(value) || limit <= 0) return [];
  const records = [];
  for (const item of value) {
    const record = recordValue(item);
    if (
      !record
      || !recoverableKeys.some((key) => Object.prototype.hasOwnProperty.call(record, key))
    ) continue;
    records.push(record);
    if (records.length >= limit) break;
  }
  return records;
}

function stringValue(value, fallback, maxLength) {
  return (typeof value === "string" ? value : fallback).slice(0, maxLength);
}

function safeId(value, fallback) {
  const id = typeof value === "string" ? value.trim().slice(0, databaseLimits.idLength) : "";
  if (id && !unsafeDatabaseIds.has(id)) return id;
  const fallbackId = fallback.slice(0, databaseLimits.idLength);
  return fallbackId && !unsafeDatabaseIds.has(fallbackId) ? fallbackId : "";
}

function uniqueId(value, seen, fallbackPrefix) {
  let id = value.slice(0, databaseLimits.idLength);
  let attempt = 1;
  while (seen.has(id)) {
    const suffix = `-${attempt}`;
    const prefixLength = Math.max(0, databaseLimits.idLength - suffix.length);
    id = `${fallbackPrefix.slice(0, prefixLength)}${suffix}`;
    attempt += 1;
  }
  seen.add(id);
  return id;
}

function createIdAliases() {
  return { exact: new Map(), generated: new Map(), normalized: new Map() };
}

function sourceStringId(value) {
  return typeof value === "string" ? value : null;
}

function sourceUsesFallbackId(value) {
  const id = typeof value === "string" ? value.trim().slice(0, databaseLimits.idLength) : "";
  return !id || unsafeDatabaseIds.has(id);
}

function registerExactIdAlias(aliases, sourceId, canonicalId) {
  if (sourceId && !aliases.exact.has(sourceId) && !aliases.generated.has(sourceId)) {
    aliases.exact.set(sourceId, canonicalId);
  }
}

function registerGeneratedIdAliases(aliases, requestedId, canonicalId) {
  [requestedId, canonicalId].forEach((alias) => {
    if (!alias || aliases.exact.has(alias) || aliases.generated.has(alias)) return;
    aliases.generated.set(alias, canonicalId);
  });
}

function registerGeneratedIdOwnership(aliases, sourceId, requestedId, canonicalId) {
  const requestedWasGenerated = sourceUsesFallbackId(sourceId);
  if (!requestedWasGenerated && canonicalId === requestedId) return;
  registerGeneratedIdAliases(
    aliases,
    requestedWasGenerated ? requestedId : "",
    canonicalId
  );
}

function registerNormalizedIdAlias(aliases, requestedId, canonicalId) {
  [requestedId, canonicalId].forEach((alias) => {
    if (
      !alias
      || aliases.exact.has(alias)
      || aliases.generated.has(alias)
      || aliases.normalized.has(alias)
    ) return;
    aliases.normalized.set(alias, canonicalId);
  });
}

function resolveIdReference(value, aliases) {
  if (typeof value !== "string") return "";
  const exact = aliases.exact.get(value);
  if (exact !== undefined) return exact;
  const generated = aliases.generated.get(value);
  if (generated !== undefined) return generated;
  const normalized = safeId(value, "");
  if (!normalized) return "";
  return aliases.exact.get(normalized)
    ?? aliases.generated.get(normalized)
    ?? aliases.normalized.get(normalized)
    ?? normalized;
}

function normalizePropertyType(value) {
  return databasePropertyTypes.includes(value) ? value : "text";
}

function normalizeViewType(value) {
  return databaseViewTypes.includes(value) ? value : "table";
}

function normalizeOptionColor(value, index) {
  return databaseOptionColors.includes(value) ? value : databaseOptionColors[index % databaseOptionColors.length];
}

function normalizeOptions(value, propertyId) {
  const aliases = createIdAliases();
  if (!Array.isArray(value)) return { options: [], aliases };
  const seen = new Set();
  const descriptors = collectRecordValues(value, databaseLimits.optionsPerProperty, ["id", "name", "color"])
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `${propertyId}-option-${index + 1}`);
      const id = uniqueId(requestedId, seen, `${propertyId}-option-${index + 1}`);
      registerGeneratedIdOwnership(aliases, item.id, requestedId, id);
      registerExactIdAlias(aliases, sourceId, id);
      return {
        sourceId,
        requestedId,
        option: {
          id,
          name: stringValue(item.name, `Option ${index + 1}`, databaseLimits.optionNameLength),
          color: normalizeOptionColor(item.color, index)
        }
      };
    });
  descriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(aliases, descriptor.requestedId, descriptor.option.id);
  });
  return { options: descriptors.map((descriptor) => descriptor.option), aliases };
}

function createDatabaseOptionValidationError(code, details = {}) {
  const error = new Error(code);
  error.code = code;
  Object.assign(error, details);
  return error;
}

export function parseDatabaseOptionNames(value) {
  const names = (typeof value === "string" ? value : "")
    .split(",")
    .map((name) => name.trim())
    .filter(Boolean);

  if (names.length > databaseLimits.optionsPerProperty) {
    throw createDatabaseOptionValidationError("too-many-options", {
      maximum: databaseLimits.optionsPerProperty
    });
  }

  const seen = new Set();
  for (const name of names) {
    if (name.length > databaseLimits.optionNameLength) {
      throw createDatabaseOptionValidationError("option-name-too-long", {
        maximum: databaseLimits.optionNameLength
      });
    }

    const normalizedName = name.toLocaleLowerCase();
    if (seen.has(normalizedName)) {
      throw createDatabaseOptionValidationError("duplicate-option", { name });
    }
    seen.add(normalizedName);
  }

  return names;
}

function databaseOptionIsReferenced(database, property, optionId) {
  const rowReference = database.rows.some((dataRow) => {
    const value = dataRow.values[property.id];
    if (property.type === "select") return value === optionId;
    return Array.isArray(value) && value.includes(optionId);
  });
  if (rowReference) return true;

  return database.views.some((view) => view.filters.some(
    (filter) => filter.propertyId === property.id && filter.value === optionId
  ));
}

export function reconcileDatabaseOptions(database, property, names) {
  const previous = property.options;
  const usedOptionIds = new Set();
  const next = Array(names.length).fill(null);

  names.forEach((name, index) => {
    const normalizedName = name.toLocaleLowerCase();
    const existing = previous.find(
      (option) => !usedOptionIds.has(option.id)
        && option.name.toLocaleLowerCase() === normalizedName
    );
    if (!existing) return;
    next[index] = { ...existing, name };
    usedOptionIds.add(existing.id);
  });

  let unmatchedOld = previous.filter((option) => !usedOptionIds.has(option.id));
  let unmatchedNewIndexes = next
    .map((option, index) => option ? null : index)
    .filter((index) => index !== null);

  // A single old/new mismatch is the only rename that the comma-separated
  // editor can identify without ambiguity. Preserve the option ID so every
  // existing row and filter continues to reference the same logical option.
  if (unmatchedOld.length === 1 && unmatchedNewIndexes.length === 1) {
    const oldOption = unmatchedOld[0];
    const index = unmatchedNewIndexes[0];
    next[index] = { ...oldOption, name: names[index] };
    usedOptionIds.add(oldOption.id);
    unmatchedOld = [];
    unmatchedNewIndexes = [];
  } else if (unmatchedOld.length > 0 && unmatchedNewIndexes.length > 0) {
    throw createDatabaseOptionValidationError("ambiguous-option-edit");
  }

  for (const index of unmatchedNewIndexes) {
    next[index] = {
      id: createId("option"),
      name: names[index],
      color: databaseOptionColors[index % databaseOptionColors.length]
    };
  }

  for (const option of unmatchedOld) {
    if (databaseOptionIsReferenced(database, property, option.id)) {
      throw createDatabaseOptionValidationError("referenced-option-removal", {
        name: option.name
      });
    }
  }

  return next.filter(Boolean);
}

function databaseOptionValidationMessage(error) {
  switch (error?.code) {
    case "too-many-options":
      return t("database.optionsTooMany", { count: error.maximum });
    case "option-name-too-long":
      return t("database.optionNameTooLong", { count: error.maximum });
    case "duplicate-option":
      return t("database.duplicateOption", { option: error.name });
    case "ambiguous-option-edit":
      return t("database.ambiguousOptionEdit");
    case "referenced-option-removal":
      return t("database.referencedOptionRemoval", { option: error.name });
    default:
      return t("database.invalidOptions");
  }
}

function normalizeFilterValue(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string") return value.slice(0, databaseLimits.textLength);
  return null;
}

function normalizePropertyValue(property, value) {
  if (property.type === "number") {
    if (value === null || value === "" || value === undefined) return null;
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
  }
  if (property.type === "checkbox") return value === true;
  if (property.type === "select") {
    const optionId = typeof value === "string" ? value : "";
    return property.options.some((option) => option.id === optionId) ? optionId : "";
  }
  if (property.type === "multi_select") {
    const values = Array.isArray(value) ? value : [];
    return [...new Set(values.filter((item) => typeof item === "string"))]
      .filter((id) => property.options.some((option) => option.id === id))
      .slice(0, databaseLimits.optionsPerProperty);
  }
  if (property.type === "date") return stringValue(value, "", 32);
  if (property.type === "url") return stringValue(value, "", databaseLimits.urlLength);
  return stringValue(value, "", databaseLimits.textLength);
}

function readSourcePropertyValue(sourceValues, descriptor, propertyAliases) {
  const candidates = [descriptor.sourceId, descriptor.requestedId, descriptor.property.id];
  const seen = new Set();
  for (const candidate of candidates) {
    if (!candidate || seen.has(candidate)) continue;
    seen.add(candidate);
    if (!Object.prototype.hasOwnProperty.call(sourceValues, candidate)) continue;
    if (resolveIdReference(candidate, propertyAliases) !== descriptor.property.id) continue;
    return sourceValues[candidate];
  }
  return undefined;
}

function normalizeReferencedPropertyValue(descriptor, value) {
  if (descriptor.property.type === "select" && typeof value === "string") {
    return normalizePropertyValue(descriptor.property, resolveIdReference(value, descriptor.optionAliases));
  }
  if (descriptor.property.type === "multi_select" && Array.isArray(value)) {
    const remapped = value.map((item) =>
      typeof item === "string" ? resolveIdReference(item, descriptor.optionAliases) : item
    );
    return normalizePropertyValue(descriptor.property, remapped);
  }
  return normalizePropertyValue(descriptor.property, value);
}

function normalizeFilterValueForProperty(descriptor, value) {
  if (["select", "multi_select"].includes(descriptor.property.type) && typeof value === "string") {
    const remapped = resolveIdReference(value, descriptor.optionAliases);
    if (descriptor.property.options.some((option) => option.id === remapped)) return remapped;
  }
  return normalizeFilterValue(value);
}

export function createDefaultDatabaseData() {
  const tableViewId = createId("view");
  const boardViewId = createId("view");
  return {
    title: t("database.defaultTitle"),
    properties: [
      { id: "title", name: t("database.defaultNameProperty"), type: "title", options: [] },
      {
        id: "status",
        name: t("database.defaultStatusProperty"),
        type: "select",
        options: [
          { id: "not-started", name: t("database.defaultNotStarted"), color: "gray" },
          { id: "in-progress", name: t("database.defaultInProgress"), color: "blue" },
          { id: "done", name: t("database.defaultDone"), color: "green" }
        ]
      },
      { id: "tags", name: t("database.defaultTagsProperty"), type: "multi_select", options: [] },
      { id: "due", name: t("database.defaultDueProperty"), type: "date", options: [] },
      { id: "complete", name: t("database.defaultCompleteProperty"), type: "checkbox", options: [] }
    ],
    rows: [
      {
        id: createId("row"),
        values: { title: "", status: "not-started", tags: [], due: "", complete: false }
      }
    ],
    views: [
      {
        id: tableViewId,
        name: t("database.tableView"),
        type: "table",
        filters: [],
        sorts: [],
        groupPropertyId: null,
        hiddenPropertyIds: []
      },
      {
        id: boardViewId,
        name: t("database.boardView"),
        type: "board",
        filters: [],
        sorts: [],
        groupPropertyId: "status",
        hiddenPropertyIds: ["status"]
      }
    ],
    activeViewId: tableViewId
  };
}

function createDatabaseNormalizationFallback() {
  return {
    title: "Database",
    views: [
      {
        id: "table-view",
        name: "Table",
        type: "table",
        filters: [],
        sorts: [],
        groupPropertyId: null,
        hiddenPropertyIds: []
      },
      {
        id: "board-view",
        name: "Board",
        type: "board",
        filters: [],
        sorts: [],
        groupPropertyId: "status",
        hiddenPropertyIds: ["status"]
      }
    ]
  };
}

export function normalizeDatabaseData(value) {
  const source = recordValue(value) ?? {};
  const fallback = createDatabaseNormalizationFallback();
  const propertySources = collectRecordValues(source.properties, databaseLimits.properties, ["id", "name", "type", "options"]);
  const seenPropertyIds = new Set();
  const propertyAliases = createIdAliases();
  let titleSeen = false;
  const propertyDescriptors = propertySources
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `property-${index + 1}`);
      const id = uniqueId(requestedId, seenPropertyIds, `property-${index + 1}`);
      registerGeneratedIdOwnership(propertyAliases, item.id, requestedId, id);
      registerExactIdAlias(propertyAliases, sourceId, id);
      let type = normalizePropertyType(item.type);
      if (type === "title") {
        if (titleSeen) type = "text";
        else titleSeen = true;
      }
      const normalizedOptions = type === "select" || type === "multi_select"
        ? normalizeOptions(item.options, id)
        : { options: [], aliases: createIdAliases() };
      return {
        sourceId,
        requestedId,
        property: {
          id,
          name: stringValue(
            item.name,
            type === "title" ? "Name" : `Property ${index + 1}`,
            databaseLimits.propertyNameLength
          ),
          type,
          options: normalizedOptions.options
        },
        optionAliases: normalizedOptions.aliases
      };
    });

  // Preserve every field in a full-capacity legacy model without a title. Adding a
  // synthetic 21st property would make the next normalization drop the final field.
  if (!titleSeen && propertyDescriptors.length < databaseLimits.properties) {
    const id = uniqueId("title", seenPropertyIds, "title");
    propertyDescriptors.unshift({
      sourceId: null,
      requestedId: id,
      property: { id, name: "Name", type: "title", options: [] },
      optionAliases: createIdAliases()
    });
  }

  propertyDescriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(propertyAliases, descriptor.requestedId, descriptor.property.id);
  });
  const properties = propertyDescriptors.map((descriptor) => descriptor.property);
  const propertyById = new Map(properties.map((property) => [property.id, property]));
  const propertyDescriptorById = new Map(
    propertyDescriptors.map((descriptor) => [descriptor.property.id, descriptor])
  );

  const rowSources = collectRecordValues(source.rows, databaseLimits.rows, ["id", "values"]);
  const seenRowIds = new Set();
  const rows = rowSources
    .map((item, index) => {
      const id = uniqueId(safeId(item.id, `row-${index + 1}`), seenRowIds, `row-${index + 1}`);
      const sourceValues = recordValue(item.values) ?? {};
      const values = {};
      propertyDescriptors.forEach((descriptor) => {
        const sourceValue = readSourcePropertyValue(sourceValues, descriptor, propertyAliases);
        values[descriptor.property.id] = normalizeReferencedPropertyValue(descriptor, sourceValue);
      });
      return { id, values };
    });

  const viewSources = collectRecordValues(
    source.views,
    databaseLimits.views,
    ["id", "name", "type", "filters", "sorts", "groupPropertyId", "hiddenPropertyIds"]
  );
  const seenViewIds = new Set();
  const viewAliases = createIdAliases();
  const viewDescriptors = viewSources
    .map((item, index) => {
      const sourceId = sourceStringId(item.id);
      const requestedId = safeId(item.id, `view-${index + 1}`);
      const id = uniqueId(requestedId, seenViewIds, `view-${index + 1}`);
      registerGeneratedIdOwnership(viewAliases, item.id, requestedId, id);
      registerExactIdAlias(viewAliases, sourceId, id);
      const type = normalizeViewType(item.type);
      const filterSources = [];
      if (Array.isArray(item.filters)) {
        for (const candidate of item.filters) {
          const filter = recordValue(candidate);
          if (!filter) continue;
          const propertyId = resolveIdReference(filter.propertyId, propertyAliases);
          if (!propertyById.has(propertyId)) continue;
          filterSources.push({ filter, propertyId });
          if (filterSources.length >= databaseLimits.filtersPerView) break;
        }
      }
      const seenFilterIds = new Set();
      const filters = filterSources.map(({ filter, propertyId }, filterIndex) => {
        const propertyDescriptor = propertyDescriptorById.get(propertyId);
        return {
          id: uniqueId(
            safeId(filter.id, `${id}-filter-${filterIndex + 1}`),
            seenFilterIds,
            `${id}-filter-${filterIndex + 1}`
          ),
          propertyId,
          operator: databaseFilterOperators.includes(filter.operator) ? filter.operator : "contains",
          value: propertyDescriptor
            ? normalizeFilterValueForProperty(propertyDescriptor, filter.value)
            : normalizeFilterValue(filter.value)
        };
      });
      const sortSources = [];
      if (Array.isArray(item.sorts)) {
        for (const candidate of item.sorts) {
          const sort = recordValue(candidate);
          if (!sort) continue;
          const propertyId = resolveIdReference(sort.propertyId, propertyAliases);
          if (!propertyById.has(propertyId)) continue;
          sortSources.push({ sort, propertyId });
          if (sortSources.length >= databaseLimits.sortsPerView) break;
        }
      }
      const seenSortIds = new Set();
      const sorts = sortSources.map(({ sort, propertyId }, sortIndex) => ({
        id: uniqueId(
          safeId(sort.id, `${id}-sort-${sortIndex + 1}`),
          seenSortIds,
          `${id}-sort-${sortIndex + 1}`
        ),
        propertyId,
        direction: sort.direction === "descending" ? "descending" : "ascending"
      }));
      const requestedGroupPropertyId = resolveIdReference(item.groupPropertyId, propertyAliases);
      const groupProperty = propertyById.get(requestedGroupPropertyId);
      const view = {
        id,
        name: stringValue(
          item.name,
          type === "board" ? "Board" : type === "list" ? "List" : "Table",
          databaseLimits.viewNameLength
        ),
        type,
        filters,
        sorts,
        groupPropertyId: type === "board" && groupProperty && ["select", "checkbox"].includes(groupProperty.type)
          ? groupProperty.id
          : null,
        hiddenPropertyIds: Array.isArray(item.hiddenPropertyIds)
          ? [...new Set(item.hiddenPropertyIds
            .filter((propertyId) => typeof propertyId === "string")
            .map((propertyId) => resolveIdReference(propertyId, propertyAliases)))]
            .filter((propertyId) => propertyById.has(propertyId) && propertyById.get(propertyId).type !== "title")
          : []
      };
      return { sourceId, requestedId, view };
    });

  viewDescriptors.forEach((descriptor) => {
    registerNormalizedIdAlias(viewAliases, descriptor.requestedId, descriptor.view.id);
  });
  const views = viewDescriptors.map((descriptor) => descriptor.view);

  const fallbackViews = fallback.views.map((view) => {
    const requestedGroupProperty = view.groupPropertyId
      ? propertyById.get(view.groupPropertyId)
      : null;
    return {
      ...view,
      groupPropertyId: view.type === "board"
        && requestedGroupProperty
        && ["select", "checkbox"].includes(requestedGroupProperty.type)
        ? requestedGroupProperty.id
        : null,
      hiddenPropertyIds: view.hiddenPropertyIds.filter(
        (propertyId) => propertyById.has(propertyId) && propertyById.get(propertyId)?.type !== "title"
      )
    };
  });
  const normalizedViews = views.length ? views : fallbackViews;
  const requestedActiveViewId = resolveIdReference(source.activeViewId, viewAliases);
  const activeViewId = normalizedViews.some((view) => view.id === requestedActiveViewId)
    ? requestedActiveViewId
    : normalizedViews[0].id;

  return {
    title: stringValue(source.title, fallback.title, databaseLimits.titleLength),
    properties,
    rows,
    views: normalizedViews,
    activeViewId
  };
}

export function getDatabaseActiveView(database) {
  return database.views.find((view) => view.id === database.activeViewId) ?? database.views[0];
}

function getTitleProperty(database) {
  return database.properties.find((property) => property.type === "title") ?? database.properties[0];
}

function getOption(property, optionId) {
  return property.options.find((option) => option.id === optionId) ?? null;
}

function isEmptyValue(value) {
  return value === null || value === "" || (Array.isArray(value) && value.length === 0);
}

function searchableValue(property, value) {
  if (property.type === "select") return getOption(property, value)?.name ?? "";
  if (property.type === "multi_select") {
    return Array.isArray(value)
      ? value.map((id) => getOption(property, id)?.name ?? "").join(" ")
      : "";
  }
  if (property.type === "checkbox") return value === true ? "true checked" : "false unchecked";
  return value === null || value === undefined ? "" : String(value);
}

function rowMatchesFilter(dataRow, filter, propertyById) {
  const property = propertyById.get(filter.propertyId);
  if (!property) return true;
  const value = dataRow.values[property.id];
  if (filter.operator === "is_empty") return isEmptyValue(value);
  if (filter.operator === "is_not_empty") return !isEmptyValue(value);
  if (filter.operator === "checked") return value === true;
  if (filter.operator === "unchecked") return value !== true;
  if (property.type === "number") {
    const filterNumber = Number(filter.value);
    return Number.isFinite(filterNumber) && value === filterNumber;
  }
  if (property.type === "select") return value === filter.value;
  if (property.type === "multi_select") {
    const values = Array.isArray(value) ? value : [];
    return filter.operator === "equals"
      ? values.length === 1 && values[0] === filter.value
      : values.includes(String(filter.value ?? ""));
  }
  const left = searchableValue(property, value).toLocaleLowerCase();
  const right = String(filter.value ?? "").toLocaleLowerCase();
  return filter.operator === "equals" ? left === right : left.includes(right);
}

function compareValues(property, left, right) {
  if (isEmptyValue(left) && isEmptyValue(right)) return 0;
  if (isEmptyValue(left)) return 1;
  if (isEmptyValue(right)) return -1;
  if (property.type === "number") return Number(left) - Number(right);
  if (property.type === "checkbox") return Number(Boolean(left)) - Number(Boolean(right));
  return searchableValue(property, left).localeCompare(searchableValue(property, right), undefined, {
    numeric: true,
    sensitivity: "base"
  });
}

export function applyDatabaseView(database, view = getDatabaseActiveView(database)) {
  const propertyById = new Map(database.properties.map((property) => [property.id, property]));
  const rows = database.rows.filter((dataRow) => view.filters.every((filter) => rowMatchesFilter(dataRow, filter, propertyById)));
  if (!view.sorts.length) return rows;
  return rows.slice().sort((left, right) => {
    for (const sort of view.sorts) {
      const property = propertyById.get(sort.propertyId);
      if (!property) continue;
      const result = compareValues(property, left.values[property.id], right.values[property.id]);
      if (result) return sort.direction === "descending" ? -result : result;
    }
    return 0;
  });
}

function applyDatabaseSearch(database, rows, query) {
  const normalizedQuery = String(query ?? "").trim().toLocaleLowerCase();
  if (!normalizedQuery) return rows;
  return rows.filter((dataRow) => database.properties.some((property) =>
    searchableValue(property, dataRow.values[property.id]).toLocaleLowerCase().includes(normalizedQuery)
  ));
}

function makeButton(action, label, title, data = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.dataset.action = action;
  button.textContent = label;
  button.title = title;
  button.setAttribute("aria-label", title);
  Object.entries(data).forEach(([key, value]) => {
    if (value !== null && value !== undefined) button.dataset[key] = String(value);
  });
  return button;
}

function makeSelect(options, value, className, ariaLabel) {
  const select = document.createElement("select");
  select.className = className;
  select.setAttribute("aria-label", ariaLabel);
  options.forEach(({ value: optionValue, label, disabled = false }) => {
    const option = document.createElement("option");
    option.value = optionValue;
    option.textContent = label;
    option.disabled = disabled;
    select.append(option);
  });
  select.value = value;
  return select;
}

function propertyTypeLabel(type) {
  return t(`database.propertyTypes.${type}`);
}

function viewTypeLabel(type) {
  return t(`database.viewTypes.${type}`);
}

function operatorLabel(operator) {
  return t(`database.operators.${operator}`);
}

function sortDirectionLabel(direction) {
  return t(`database.sortDirections.${direction}`);
}

const databaseUrlPreviewCache = new Map();
const databaseUrlPreviewCacheMaxEntries = 250;
const databaseUrlPreviewObservers = new WeakMap();

function getDatabasePreviewUrl(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw) return null;
  try {
    const url = new URL(raw);
    if (!["http:", "https:"].includes(url.protocol) || url.username || url.password) return null;
    return url;
  } catch {
    return null;
  }
}

const databaseUrlPreviewFaviconDataUrlMaxLength = Math.ceil((128 * 1024 * 4) / 3) + 128;
const databaseUrlPreviewFaviconDataPattern = /^data:image\/(?:png|jpeg|gif|webp|vnd\.microsoft\.icon);base64,[a-z0-9+/]+={0,2}$/i;

function getDatabasePreviewImageUrl(value) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (
    raw.length <= databaseUrlPreviewFaviconDataUrlMaxLength
    && databaseUrlPreviewFaviconDataPattern.test(raw)
  ) return raw;
  const url = getDatabasePreviewUrl(raw);
  return url?.toString() ?? "";
}

function resetDatabaseUrlPreview(preview, value) {
  const raw = typeof value === "string" ? value : "";
  const url = getDatabasePreviewUrl(raw);
  preview.replaceChildren();
  preview.classList.toggle("is-empty", !raw);
  preview.classList.toggle("is-invalid", Boolean(raw) && !url);
  preview.dataset.previewState = url ? "pending" : "idle";

  if (url) {
    const normalizedUrl = url.toString();
    preview.href = normalizedUrl;
    preview.dataset.url = normalizedUrl;
  } else {
    preview.removeAttribute("href");
    delete preview.dataset.url;
  }

  const faviconSlot = document.createElement("span");
  faviconSlot.className = "database-url-preview-favicon";
  faviconSlot.setAttribute("aria-hidden", "true");

  const title = document.createElement("span");
  title.className = "database-url-preview-title";
  title.textContent = url ? url.hostname : raw;
  preview.append(faviconSlot, title);
}

function applyDatabaseUrlPreview(preview, previewData, requestedUrl) {
  if (!preview?.isConnected || preview.dataset.url !== requestedUrl) return;
  const title = typeof previewData?.title === "string" ? previewData.title.trim() : "";
  const titleElement = preview.querySelector(".database-url-preview-title");
  if (titleElement && title) titleElement.textContent = title;

  const faviconUrl = getDatabasePreviewImageUrl(previewData?.faviconUrl);
  const faviconSlot = preview.querySelector(".database-url-preview-favicon");
  if (faviconSlot) {
    faviconSlot.replaceChildren();
    if (faviconUrl) {
      const image = document.createElement("img");
      image.src = faviconUrl;
      image.alt = "";
      image.width = 16;
      image.height = 16;
      image.loading = "lazy";
      image.referrerPolicy = "no-referrer";
      image.addEventListener("error", () => image.remove(), { once: true });
      faviconSlot.append(image);
    }
  }
  preview.dataset.previewState = "loaded";
}

function getDatabaseUrlPreviewRequest(url, fetchPreview) {
  const cached = databaseUrlPreviewCache.get(url);
  if (cached) {
    // Keep frequently reused previews resident when one-off URLs churn through
    // the bounded cache; Map iteration order is insertion order.
    databaseUrlPreviewCache.delete(url);
    databaseUrlPreviewCache.set(url, cached);
    return cached;
  }

  const request = Promise.resolve()
    .then(() => fetchPreview(url))
    .then((value) => value?.preview ?? value ?? null)
    .catch(() => null)
    .then((value) => {
      // Do not let a late failure from an evicted request delete a newer
      // in-flight/result entry for the same URL.
      if (!value && databaseUrlPreviewCache.get(url) === request) {
        databaseUrlPreviewCache.delete(url);
      }
      return value;
    });
  databaseUrlPreviewCache.set(url, request);
  if (databaseUrlPreviewCache.size > databaseUrlPreviewCacheMaxEntries) {
    const oldest = databaseUrlPreviewCache.keys().next().value;
    if (oldest) databaseUrlPreviewCache.delete(oldest);
  }
  return request;
}

async function hydrateDatabaseUrlPreview(preview, fetchPreview) {
  const url = preview?.dataset?.url;
  if (!url || preview.dataset.previewState === "loading" || preview.dataset.previewState === "loaded") return;
  preview.dataset.previewState = "loading";
  const previewData = await getDatabaseUrlPreviewRequest(url, fetchPreview);
  if (!preview?.isConnected || preview.dataset.url !== url) return;
  if (!previewData) {
    preview.dataset.previewState = "failed";
    return;
  }
  applyDatabaseUrlPreview(preview, previewData, url);
}

export function hydrateDatabaseUrlPreviews(root, fetchPreview) {
  if (!root || typeof fetchPreview !== "function") return;
  // `root` is normally the long-lived page view. Release targets from the
  // previous render even when the new render has no URL previews, otherwise an
  // IntersectionObserver can keep detached offscreen preview nodes registered.
  let observerState = databaseUrlPreviewObservers.get(root);
  observerState?.observer?.disconnect();
  const previews = [...root.querySelectorAll(".database-url-preview[data-url]")]
    .filter((preview) => !["loading", "loaded"].includes(preview.dataset.previewState));
  if (!previews.length) return;

  if (typeof IntersectionObserver !== "function") {
    previews.forEach((preview) => { void hydrateDatabaseUrlPreview(preview, fetchPreview); });
    return;
  }

  if (!observerState || observerState.fetchPreview !== fetchPreview) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        observer.unobserve(entry.target);
        void hydrateDatabaseUrlPreview(entry.target, fetchPreview);
      });
    }, { rootMargin: "160px" });
    observerState = { observer, fetchPreview };
    databaseUrlPreviewObservers.set(root, observerState);
  }
  previews.forEach((preview) => observerState.observer.observe(preview));
}

function createValueEditor(dataRow, property, { compact = false, onDirty, onStructuralChange = null } = {}) {
  const value = dataRow.values[property.id];
  let control;
  let urlPreview = null;
  let urlValue = null;

  if (property.type === "checkbox") {
    control = document.createElement("input");
    control.type = "checkbox";
    control.checked = value === true;
  } else if (property.type === "select") {
    control = makeSelect(
      [{ value: "", label: t("database.noValue") }, ...property.options.map((option) => ({ value: option.id, label: option.name }))],
      typeof value === "string" ? value : "",
      "database-value-select",
      property.name
    );
    control.classList.add("database-select-chip");
    control.dataset.optionColor = getOption(property, control.value)?.color ?? "gray";
  } else {
    control = document.createElement("input");
    control.type = property.type === "number" ? "number" : property.type === "date" ? "date" : "text";
    control.value = property.type === "multi_select"
      ? (Array.isArray(value) ? value.map((id) => getOption(property, id)?.name).filter(Boolean).join(", ") : "")
      : value === null || value === undefined ? "" : String(value);
    control.maxLength = property.type === "url" ? databaseLimits.urlLength : databaseLimits.textLength;
    if (property.type === "url") control.inputMode = "url";
    if (property.type === "number") control.inputMode = "decimal";
    control.placeholder = property.type === "multi_select" ? t("database.multiSelectPlaceholder") : "";
  }

  control.classList.add("database-value-input");
  if (compact) control.classList.add("is-compact");
  control.dataset.rowId = dataRow.id;
  control.dataset.propertyId = property.id;
  control.setAttribute("aria-label", t("database.valueAria", { property: property.name }));

  if (property.type === "url") {
    urlValue = document.createElement("span");
    urlValue.className = "database-url-value";
    if (compact) urlValue.classList.add("is-compact");
    urlPreview = document.createElement("a");
    urlPreview.className = "database-url-preview";
    urlPreview.target = "_blank";
    urlPreview.rel = "noopener noreferrer";
    urlPreview.referrerPolicy = "no-referrer";
    resetDatabaseUrlPreview(urlPreview, control.value);
    urlValue.append(control, urlPreview);
  }

  const updateEvent = property.type === "checkbox" || property.type === "select" || property.type === "date" ? "change" : "input";
  const update = () => {
    if (property.type === "checkbox") dataRow.values[property.id] = control.checked;
    else if (property.type === "number") dataRow.values[property.id] = control.value === "" ? null : Number(control.value);
    else if (property.type === "multi_select") {
      const names = control.value.split(",").map((item) => item.trim().toLocaleLowerCase()).filter(Boolean);
      dataRow.values[property.id] = property.options
        .filter((option) => names.includes(option.name.toLocaleLowerCase()))
        .map((option) => option.id);
    } else dataRow.values[property.id] = control.value;
    if (property.type === "select") control.dataset.optionColor = getOption(property, control.value)?.color ?? "gray";
    if (urlPreview) resetDatabaseUrlPreview(urlPreview, control.value);
    onDirty();
    if (onStructuralChange && updateEvent === "change") onStructuralChange();
  };

  control.addEventListener(updateEvent, update);
  if (onStructuralChange && updateEvent === "input") control.addEventListener("change", onStructuralChange);
  return urlValue ?? control;
}

function createPropertyManager(editor, row, database, onDirty, replaceEditor) {
  const details = document.createElement("details");
  details.className = "database-properties-panel";

  const summary = document.createElement("summary");
  summary.textContent = t("database.properties");
  details.append(summary);

  const list = document.createElement("div");
  list.className = "database-property-list";

  database.properties.forEach((property) => {
    const item = document.createElement("div");
    item.className = "database-property-item";
    item.dataset.propertyId = property.id;

    const name = document.createElement("input");
    name.type = "text";
    name.className = "database-property-name";
    name.value = property.name;
    name.maxLength = databaseLimits.propertyNameLength;
    name.setAttribute("aria-label", t("database.propertyName"));
    name.addEventListener("input", () => {
      property.name = name.value.slice(0, databaseLimits.propertyNameLength);
      editor.querySelectorAll(`[data-property-label="${CSS.escape(property.id)}"]`).forEach((label) => {
        label.textContent = property.name;
      });
      onDirty();
    });

    const type = makeSelect(
      databasePropertyTypes.map((propertyType) => ({
        value: propertyType,
        label: propertyTypeLabel(propertyType),
        disabled: property.type === "title" ? propertyType !== "title" : propertyType === "title"
      })),
      property.type,
      "database-property-type",
      t("database.propertyType")
    );
    type.disabled = property.type === "title";
    type.addEventListener("change", () => {
      property.type = normalizePropertyType(type.value);
      if (!["select", "multi_select"].includes(property.type)) property.options = [];
      database.rows.forEach((dataRow) => {
        dataRow.values[property.id] = normalizePropertyValue(property, dataRow.values[property.id]);
      });
      replaceEditor({ openProperties: true, focusPropertyId: property.id });
    });

    item.append(name, type);

    if (["select", "multi_select"].includes(property.type)) {
      const options = document.createElement("input");
      options.type = "text";
      options.className = "database-property-options";
      options.value = property.options.map((option) => option.name).join(", ");
      options.placeholder = t("database.optionsPlaceholder");
      options.setAttribute("aria-label", t("database.options"));
      options.addEventListener("change", () => {
        try {
          const names = parseDatabaseOptionNames(options.value);
          const nextOptions = reconcileDatabaseOptions(database, property, names);
          options.setCustomValidity("");
          property.options = nextOptions;
          replaceEditor({ openProperties: true, focusPropertyId: property.id });
        } catch (error) {
          options.setCustomValidity(databaseOptionValidationMessage(error));
          options.reportValidity();
          // Fail closed: keep the user's raw input visible, do not mutate the
          // canonical model, and do not trigger autosave.
        }
      });
      item.append(options);
    }

    const visibility = document.createElement("label");
    visibility.className = "database-property-visibility";
    const visible = document.createElement("input");
    visible.type = "checkbox";
    visible.checked = !getDatabaseActiveView(database).hiddenPropertyIds.includes(property.id);
    visible.disabled = property.type === "title";
    visible.addEventListener("change", () => {
      const view = getDatabaseActiveView(database);
      view.hiddenPropertyIds = visible.checked
        ? view.hiddenPropertyIds.filter((id) => id !== property.id)
        : [...new Set([...view.hiddenPropertyIds, property.id])];
      replaceEditor({ openProperties: true, focusPropertyId: property.id });
    });
    visibility.append(visible, document.createTextNode(t("database.visibleInView")));
    item.append(visibility);

    const remove = makeButton("database-delete-property", "×", t("database.deleteProperty"), { propertyId: property.id });
    remove.className = "database-property-delete";
    remove.disabled = property.type === "title" || database.properties.length <= 1;
    item.append(remove);
    list.append(item);
  });

  const add = makeButton("database-add-property", `＋ ${t("database.addProperty")}`, t("database.addProperty"));
  add.className = "database-add-property";
  add.disabled = database.properties.length >= databaseLimits.properties;
  list.append(add);
  details.append(list);
  return details;
}

function validOperatorsForProperty(property) {
  if (property.type === "checkbox") return ["checked", "unchecked"];
  if (["number", "select", "date"].includes(property.type)) return ["equals", "is_empty", "is_not_empty"];
  return ["contains", "equals", "is_empty", "is_not_empty"];
}

function createFilterValueControl(property, operator) {
  if (["is_empty", "is_not_empty", "checked", "unchecked"].includes(operator)) {
    const hidden = document.createElement("input");
    hidden.type = "hidden";
    hidden.value = "";
    return hidden;
  }
  if (property.type === "select" || property.type === "multi_select") {
    return makeSelect(
      property.options.map((option) => ({ value: option.id, label: option.name })),
      property.options[0]?.id ?? "",
      "database-filter-value",
      t("database.filterValue")
    );
  }
  const input = document.createElement("input");
  input.className = "database-filter-value";
  input.type = property.type === "number" ? "number" : property.type === "date" ? "date" : "text";
  input.placeholder = t("database.filterValue");
  input.setAttribute("aria-label", t("database.filterValue"));
  return input;
}

function createViewSettings(editor, row, database, onDirty, replaceEditor) {
  const view = getDatabaseActiveView(database);
  const panel = document.createElement("div");
  panel.className = "database-view-settings";

  const filters = document.createElement("details");
  filters.className = "database-rule-panel database-filter-panel";
  const filterSummary = document.createElement("summary");
  filterSummary.textContent = `${t("database.filter")}${view.filters.length ? ` ${formatNumber(view.filters.length)}` : ""}`;
  filters.append(filterSummary);

  const filterPopover = document.createElement("div");
  filterPopover.className = "database-toolbar-popover database-rule-popover";
  const filterBuilder = document.createElement("div");
  filterBuilder.className = "database-rule-builder";
  const filterProperty = makeSelect(
    database.properties.map((property) => ({ value: property.id, label: property.name })),
    database.properties[0]?.id ?? "",
    "database-filter-property",
    t("database.filterProperty")
  );
  let selectedFilterProperty = database.properties.find((property) => property.id === filterProperty.value) ?? database.properties[0];
  let filterOperator = makeSelect(
    validOperatorsForProperty(selectedFilterProperty).map((operator) => ({ value: operator, label: operatorLabel(operator) })),
    validOperatorsForProperty(selectedFilterProperty)[0],
    "database-filter-operator",
    t("database.filterOperator")
  );
  let filterValue = createFilterValueControl(selectedFilterProperty, filterOperator.value);

  const rebuildFilterValue = () => {
    const next = createFilterValueControl(selectedFilterProperty, filterOperator.value);
    filterValue.replaceWith(next);
    filterValue = next;
  };

  const rebuildFilterControls = () => {
    selectedFilterProperty = database.properties.find((property) => property.id === filterProperty.value) ?? database.properties[0];
    const operatorOptions = validOperatorsForProperty(selectedFilterProperty);
    const nextOperator = operatorOptions.includes(filterOperator.value) ? filterOperator.value : operatorOptions[0];
    const nextOperatorControl = makeSelect(
      operatorOptions.map((operator) => ({ value: operator, label: operatorLabel(operator) })),
      nextOperator,
      "database-filter-operator",
      t("database.filterOperator")
    );
    nextOperatorControl.addEventListener("change", rebuildFilterValue);
    filterOperator.replaceWith(nextOperatorControl);
    filterOperator = nextOperatorControl;
    rebuildFilterValue();
  };

  filterProperty.addEventListener("change", rebuildFilterControls);
  filterOperator.addEventListener("change", rebuildFilterValue);

  const addFilter = makeButton("database-add-filter", t("database.addFilter"), t("database.addFilter"));
  addFilter.addEventListener("click", () => {
    if (view.filters.length >= databaseLimits.filtersPerView) return;
    view.filters.push({
      id: createId("filter"),
      propertyId: selectedFilterProperty.id,
      operator: filterOperator.value,
      value: selectedFilterProperty.type === "number" && filterValue.value !== "" ? Number(filterValue.value) : filterValue.value
    });
    replaceEditor({ openFilters: true });
  });
  filterBuilder.append(filterProperty, filterOperator, filterValue, addFilter);
  filterPopover.append(filterBuilder);

  if (view.filters.length) {
    const chips = document.createElement("div");
    chips.className = "database-rule-chips";
    view.filters.forEach((filter) => {
      const property = database.properties.find((item) => item.id === filter.propertyId);
      const chip = makeButton(
        "database-remove-filter",
        `${property?.name ?? "?"} · ${operatorLabel(filter.operator)}${filter.value !== null && filter.value !== "" ? ` · ${property?.type === "select" || property?.type === "multi_select" ? getOption(property, filter.value)?.name ?? filter.value : filter.value}` : ""} ×`,
        t("database.removeFilter"),
        { filterId: filter.id }
      );
      chip.className = "database-rule-chip";
      chips.append(chip);
    });
    filterPopover.append(chips);
  }
  filters.append(filterPopover);
  panel.append(filters);

  const sorts = document.createElement("details");
  sorts.className = "database-rule-panel database-sort-panel";
  const sortSummary = document.createElement("summary");
  sortSummary.textContent = `${t("database.sort")}${view.sorts.length ? ` ${formatNumber(view.sorts.length)}` : ""}`;
  sorts.append(sortSummary);

  const sortPopover = document.createElement("div");
  sortPopover.className = "database-toolbar-popover database-rule-popover";
  const sortBuilder = document.createElement("div");
  sortBuilder.className = "database-rule-builder";
  const sortProperty = makeSelect(
    database.properties.map((property) => ({ value: property.id, label: property.name })),
    database.properties[0]?.id ?? "",
    "database-sort-property",
    t("database.sortProperty")
  );
  const sortDirection = makeSelect(
    ["ascending", "descending"].map((direction) => ({ value: direction, label: sortDirectionLabel(direction) })),
    "ascending",
    "database-sort-direction",
    t("database.sortDirection")
  );
  const addSort = makeButton("database-add-sort", t("database.addSort"), t("database.addSort"));
  addSort.addEventListener("click", () => {
    if (view.sorts.length >= databaseLimits.sortsPerView) return;
    view.sorts.push({ id: createId("sort"), propertyId: sortProperty.value, direction: sortDirection.value });
    replaceEditor({ openSorts: true });
  });
  sortBuilder.append(sortProperty, sortDirection, addSort);
  sortPopover.append(sortBuilder);

  if (view.sorts.length) {
    const chips = document.createElement("div");
    chips.className = "database-rule-chips";
    view.sorts.forEach((sort) => {
      const property = database.properties.find((item) => item.id === sort.propertyId);
      const chip = makeButton(
        "database-remove-sort",
        `${property?.name ?? "?"} · ${sortDirectionLabel(sort.direction)} ×`,
        t("database.removeSort"),
        { sortId: sort.id }
      );
      chip.className = "database-rule-chip";
      chips.append(chip);
    });
    sortPopover.append(chips);
  }
  sorts.append(sortPopover);
  panel.append(sorts);

  const viewOptions = document.createElement("details");
  viewOptions.className = "database-view-options-panel";
  const viewOptionsSummary = document.createElement("summary");
  viewOptionsSummary.textContent = "•••";
  viewOptionsSummary.title = t("database.viewOptions");
  viewOptionsSummary.setAttribute("aria-label", t("database.viewOptions"));
  viewOptions.append(viewOptionsSummary);

  const viewOptionsMenu = document.createElement("div");
  viewOptionsMenu.className = "database-toolbar-popover database-view-options-menu";

  const viewNameLabel = document.createElement("label");
  viewNameLabel.className = "database-settings-field";
  const viewNameCaption = document.createElement("span");
  viewNameCaption.textContent = t("database.viewName");
  const viewName = document.createElement("input");
  viewName.type = "text";
  viewName.className = "database-view-name";
  viewName.value = view.name;
  viewName.maxLength = databaseLimits.viewNameLength;
  viewName.setAttribute("aria-label", t("database.viewName"));
  viewName.addEventListener("input", () => {
    view.name = viewName.value.slice(0, databaseLimits.viewNameLength);
    const tabLabel = editor.querySelector(`[data-view-tab="${CSS.escape(view.id)}"] .database-view-tab-label`);
    if (tabLabel) tabLabel.textContent = view.name;
    onDirty();
  });
  viewNameLabel.append(viewNameCaption, viewName);

  const viewTypeLabelElement = document.createElement("label");
  viewTypeLabelElement.className = "database-settings-field";
  const viewTypeCaption = document.createElement("span");
  viewTypeCaption.textContent = t("database.viewType");
  const viewType = makeSelect(
    databaseViewTypes.map((type) => ({ value: type, label: viewTypeLabel(type) })),
    view.type,
    "database-view-type",
    t("database.viewType")
  );
  viewType.addEventListener("change", () => {
    view.type = normalizeViewType(viewType.value);
    if (view.type === "board") {
      const groupProperty = database.properties.find((property) => ["select", "checkbox"].includes(property.type));
      view.groupPropertyId = groupProperty?.id ?? null;
    }
    replaceEditor({ openViewOptions: true, focusViewName: true });
  });
  viewTypeLabelElement.append(viewTypeCaption, viewType);
  viewOptionsMenu.append(viewNameLabel, viewTypeLabelElement);

  if (view.type === "board") {
    const groupProperties = database.properties.filter((property) => ["select", "checkbox"].includes(property.type));
    const groupLabel = document.createElement("label");
    groupLabel.className = "database-settings-field";
    const groupCaption = document.createElement("span");
    groupCaption.textContent = t("database.groupBy");
    const groupBy = makeSelect(
      [{ value: "", label: t("database.noGrouping") }, ...groupProperties.map((property) => ({ value: property.id, label: property.name }))],
      view.groupPropertyId ?? "",
      "database-group-property",
      t("database.groupBy")
    );
    groupBy.addEventListener("change", () => {
      view.groupPropertyId = groupBy.value || null;
      replaceEditor({ openViewOptions: true });
    });
    groupLabel.append(groupCaption, groupBy);
    viewOptionsMenu.append(groupLabel);
  }

  const removeView = makeButton("database-delete-view", t("database.deleteView"), t("database.deleteView"));
  removeView.className = "database-delete-view";
  removeView.disabled = database.views.length <= 1;
  viewOptionsMenu.append(removeView);
  viewOptions.append(viewOptionsMenu);
  panel.append(viewOptions);

  return panel;
}

function createTableView(row, database, view, rows, onDirty, replaceEditor) {
  const viewSensitivePropertyIds = new Set([...view.filters, ...view.sorts].map((rule) => rule.propertyId));
  const visibleProperties = database.properties.filter((property) => !view.hiddenPropertyIds.includes(property.id));
  const scroller = document.createElement("div");
  scroller.className = "database-table-scroll";
  const table = document.createElement("table");
  table.className = "database-table";
  table.setAttribute("aria-label", t("database.tableAria"));

  const thead = document.createElement("thead");
  const header = document.createElement("tr");
  visibleProperties.forEach((property) => {
    const th = document.createElement("th");
    th.dataset.propertyLabel = property.id;
    th.dataset.propertyType = property.type;
    th.textContent = property.name;
    header.append(th);
  });
  thead.append(header);

  const tbody = document.createElement("tbody");
  rows.forEach((dataRow) => {
    const tr = document.createElement("tr");
    tr.dataset.databaseRowId = dataRow.id;
    visibleProperties.forEach((property) => {
      const td = document.createElement("td");
      td.dataset.propertyType = property.type;
      const valueEditor = createValueEditor(dataRow, property, {
        onDirty,
        onStructuralChange: viewSensitivePropertyIds.has(property.id) ? () => replaceEditor() : null
      });
      if (property.type === "title") {
        const titleCell = document.createElement("div");
        titleCell.className = "database-title-cell";
        const pageIcon = document.createElement("span");
        pageIcon.className = "database-title-cell-icon";
        pageIcon.textContent = "▤";
        pageIcon.setAttribute("aria-hidden", "true");
        valueEditor.classList.add("database-title-value");
        titleCell.append(pageIcon, valueEditor);
        td.append(titleCell);
      } else {
        td.append(valueEditor);
      }
      tr.append(td);
    });
    const remove = makeButton("database-delete-row", "×", t("database.deleteRow"), { rowId: dataRow.id });
    remove.className = "database-delete-row database-table-delete-row";
    tr.lastElementChild?.append(remove);
    tbody.append(tr);
  });

  table.append(thead, tbody);
  scroller.append(table);
  return scroller;
}

function createListView(row, database, view, rows, onDirty, replaceEditor) {
  const viewSensitivePropertyIds = new Set([...view.filters, ...view.sorts].map((rule) => rule.propertyId));
  const titleProperty = getTitleProperty(database);
  const visibleProperties = database.properties.filter(
    (property) => property.id !== titleProperty.id && !view.hiddenPropertyIds.includes(property.id)
  );
  const list = document.createElement("div");
  list.className = "database-list-view";
  rows.forEach((dataRow) => {
    const item = document.createElement("article");
    item.className = "database-list-row";
    item.dataset.databaseRowId = dataRow.id;
    const title = createValueEditor(dataRow, titleProperty, {
      onDirty,
      onStructuralChange: viewSensitivePropertyIds.has(titleProperty.id) ? () => replaceEditor() : null
    });
    title.classList.add("database-list-title");
    const properties = document.createElement("div");
    properties.className = "database-list-properties";
    visibleProperties.forEach((property) => {
      const field = document.createElement("label");
      field.className = "database-list-field";
      const label = document.createElement("span");
      label.dataset.propertyLabel = property.id;
      label.textContent = property.name;
      field.append(label, createValueEditor(dataRow, property, {
        compact: true,
        onDirty,
        onStructuralChange: viewSensitivePropertyIds.has(property.id) ? () => replaceEditor() : null
      }));
      properties.append(field);
    });
    const remove = makeButton("database-delete-row", "×", t("database.deleteRow"), { rowId: dataRow.id });
    remove.className = "database-delete-row";
    item.append(title, properties, remove);
    list.append(item);
  });
  return list;
}

function createBoardView(row, database, view, rows, onDirty, replaceEditor) {
  const viewSensitivePropertyIds = new Set([...view.filters, ...view.sorts].map((rule) => rule.propertyId));
  const titleProperty = getTitleProperty(database);
  const groupProperty = database.properties.find((property) => property.id === view.groupPropertyId) ?? null;
  const visibleProperties = database.properties.filter(
    (property) => property.id !== titleProperty.id && property.id !== groupProperty?.id && !view.hiddenPropertyIds.includes(property.id)
  );
  const groups = [];
  if (groupProperty?.type === "select") {
    groupProperty.options.forEach((option) => groups.push({ id: option.id, name: option.name, color: option.color, rows: [] }));
    groups.push({ id: "", name: t("database.noValue"), color: "gray", rows: [] });
  } else if (groupProperty?.type === "checkbox") {
    groups.push(
      { id: "false", name: t("database.unchecked"), color: "gray", rows: [] },
      { id: "true", name: t("database.checked"), color: "green", rows: [] }
    );
  } else {
    groups.push({ id: "all", name: t("database.allRows"), color: "gray", rows: [] });
  }

  rows.forEach((dataRow) => {
    const value = groupProperty ? dataRow.values[groupProperty.id] : "all";
    const groupId = groupProperty?.type === "checkbox" ? String(value === true) : String(value ?? "");
    (groups.find((group) => group.id === groupId) ?? groups[groups.length - 1]).rows.push(dataRow);
  });

  const scroller = document.createElement("div");
  scroller.className = "database-board-scroll";
  const board = document.createElement("div");
  board.className = "database-board";
  board.setAttribute("aria-label", t("database.boardAria"));

  groups.forEach((group) => {
    const column = document.createElement("section");
    column.className = "database-board-column";
    column.dataset.optionColor = group.color;
    const heading = document.createElement("header");
    const name = document.createElement("strong");
    name.textContent = group.name;
    const count = document.createElement("span");
    count.textContent = formatNumber(group.rows.length);
    heading.append(name, count);

    const cards = document.createElement("div");
    cards.className = "database-board-cards";
    group.rows.forEach((dataRow) => {
      const card = document.createElement("article");
      card.className = "database-board-card";
      card.dataset.databaseRowId = dataRow.id;
      const title = createValueEditor(dataRow, titleProperty, {
        onDirty,
        onStructuralChange: viewSensitivePropertyIds.has(titleProperty.id) ? () => replaceEditor() : null
      });
      title.classList.add("database-board-card-title");
      card.append(title);

      if (groupProperty) {
        const groupField = document.createElement("label");
        groupField.className = "database-board-group-field";
        const groupLabel = document.createElement("span");
        groupLabel.textContent = groupProperty.name;
        const groupEditor = createValueEditor(dataRow, groupProperty, {
          compact: true,
          onDirty,
          onStructuralChange: () => replaceEditor({ focusRowId: dataRow.id })
        });
        groupField.append(groupLabel, groupEditor);
        card.append(groupField);
      }

      visibleProperties.forEach((property) => {
        const field = document.createElement("label");
        field.className = "database-board-card-field";
        const label = document.createElement("span");
        label.dataset.propertyLabel = property.id;
        label.textContent = property.name;
        field.append(label, createValueEditor(dataRow, property, {
          compact: true,
          onDirty,
          onStructuralChange: viewSensitivePropertyIds.has(property.id) ? () => replaceEditor() : null
        }));
        card.append(field);
      });
      const remove = makeButton("database-delete-row", "×", t("database.deleteRow"), { rowId: dataRow.id });
      remove.className = "database-delete-row";
      card.append(remove);
      cards.append(card);
    });

    const add = makeButton("database-add-row", `＋ ${t("database.newRow")}`, t("database.newRow"), {
      groupPropertyId: groupProperty?.id ?? "",
      groupValue: group.id
    });
    add.className = "database-board-add-row";
    add.disabled = database.rows.length >= databaseLimits.rows;
    column.append(heading, cards, add);
    board.append(column);
  });

  scroller.append(board);
  return scroller;
}

export function createDatabaseEditor(row, value, { onDirty = () => {} } = {}) {
  const database = normalizeDatabaseData(value);
  const editor = document.createElement("div");
  editor.className = "database-block-editor";
  editor.databaseData = database;

  const replaceEditor = (focus = {}) => {
    const host = row.querySelector(".block-editor-host");
    if (!host) return;
    const reopen = {
      openProperties: Boolean(focus.openProperties) && !consumeDatabaseToolbarLightDismiss(row, "openProperties"),
      openFilters: Boolean(focus.openFilters) && !consumeDatabaseToolbarLightDismiss(row, "openFilters"),
      openSorts: Boolean(focus.openSorts) && !consumeDatabaseToolbarLightDismiss(row, "openSorts"),
      openViewOptions: Boolean(focus.openViewOptions) && !consumeDatabaseToolbarLightDismiss(row, "openViewOptions")
    };
    const next = createDatabaseEditor(row, database, { onDirty });
    host.replaceChildren(next);
    onDirty();
    requestAnimationFrame(() => {
      if (reopen.openProperties) next.querySelector(".database-properties-panel")?.setAttribute("open", "");
      if (reopen.openFilters) next.querySelector(".database-filter-panel")?.setAttribute("open", "");
      if (reopen.openSorts) next.querySelector(".database-sort-panel")?.setAttribute("open", "");
      if (reopen.openViewOptions) next.querySelector(".database-view-options-panel")?.setAttribute("open", "");
      if (focus.focusPropertyId && reopen.openProperties) next.querySelector(`.database-property-item[data-property-id="${CSS.escape(focus.focusPropertyId)}"] .database-property-name`)?.focus();
      else if (focus.focusViewName && reopen.openViewOptions) next.querySelector(".database-view-name")?.focus();
      else if (focus.focusRowId) next.querySelector(`[data-database-row-id="${CSS.escape(focus.focusRowId)}"] .database-value-input`)?.focus();
    });
  };

  const heading = document.createElement("div");
  heading.className = "database-heading";
  const title = document.createElement("input");
  title.type = "text";
  title.className = "database-title-input";
  title.value = database.title;
  title.maxLength = databaseLimits.titleLength;
  title.placeholder = t("database.titlePlaceholder");
  title.setAttribute("aria-label", t("database.titleAria"));
  title.addEventListener("input", () => {
    database.title = title.value.slice(0, databaseLimits.titleLength);
    onDirty();
  });
  const count = document.createElement("span");
  count.className = "database-count";
  count.textContent = t("database.rowCount", { count: formatNumber(database.rows.length) });
  heading.append(title, count);

  const toolbar = document.createElement("div");
  toolbar.className = "database-toolbar";

  const viewBar = document.createElement("div");
  viewBar.className = "database-view-bar";
  database.views.forEach((view) => {
    const tab = makeButton("database-select-view", "", t("database.selectView", { view: view.name }), { viewId: view.id });
    tab.className = "database-view-tab";
    tab.dataset.viewTab = view.id;
    tab.dataset.viewType = view.type;
    tab.setAttribute("aria-pressed", String(view.id === database.activeViewId));
    const icon = document.createElement("span");
    icon.className = "database-view-tab-icon";
    icon.setAttribute("aria-hidden", "true");
    const label = document.createElement("span");
    label.className = "database-view-tab-label";
    label.textContent = view.name;
    tab.append(icon, label);
    viewBar.append(tab);
  });

  const addView = makeSelect(
    [
      { value: "", label: "+" },
      ...databaseViewTypes.map((type) => ({ value: type, label: viewTypeLabel(type) }))
    ],
    "",
    "database-add-view-select",
    t("database.addView")
  );
  addView.title = t("database.addView");
  addView.disabled = database.views.length >= databaseLimits.views;
  addView.addEventListener("change", () => {
    if (!addView.value) return;
    const type = normalizeViewType(addView.value);
    const groupProperty = database.properties.find((property) => ["select", "checkbox"].includes(property.type));
    const view = {
      id: createId("view"),
      name: viewTypeLabel(type),
      type,
      filters: [],
      sorts: [],
      groupPropertyId: type === "board" ? groupProperty?.id ?? null : null,
      hiddenPropertyIds: []
    };
    database.views.push(view);
    database.activeViewId = view.id;
    replaceEditor({ openViewOptions: true, focusViewName: true });
  });
  viewBar.append(addView);

  const activeView = getDatabaseActiveView(database);
  const viewRows = applyDatabaseView(database, activeView);
  const settings = createViewSettings(editor, row, database, onDirty, replaceEditor);
  const properties = createPropertyManager(editor, row, database, onDirty, replaceEditor);
  settings.prepend(properties);

  const searchPanel = document.createElement("details");
  searchPanel.className = "database-search-panel";
  const searchSummary = document.createElement("summary");
  searchSummary.textContent = `⌕ ${t("database.search")}`;
  searchSummary.setAttribute("aria-label", t("database.search"));
  const searchPopover = document.createElement("div");
  searchPopover.className = "database-toolbar-popover database-search-popover";
  const searchInput = document.createElement("input");
  searchInput.type = "search";
  searchInput.className = "database-search-input";
  searchInput.placeholder = t("database.searchPlaceholder");
  searchInput.setAttribute("aria-label", t("database.search"));
  searchPopover.append(searchInput);
  searchPanel.append(searchSummary, searchPopover);
  settings.append(searchPanel);

  const newButtonGroup = document.createElement("div");
  newButtonGroup.className = "database-new-button-group";
  const newRowButton = makeButton("database-add-row", t("database.newItem"), t("database.newRow"));
  newRowButton.className = "database-new-row-button";
  newRowButton.disabled = database.rows.length >= databaseLimits.rows;
  const newMenu = document.createElement("details");
  newMenu.className = "database-new-menu";
  const newMenuSummary = document.createElement("summary");
  newMenuSummary.textContent = "⌄";
  newMenuSummary.setAttribute("aria-label", t("database.newOptions"));
  const newMenuPopover = document.createElement("div");
  newMenuPopover.className = "database-toolbar-popover database-new-menu-popover";
  const newMenuRowButton = makeButton("database-add-row", `＋ ${t("database.newRow")}`, t("database.newRow"));
  newMenuPopover.append(newMenuRowButton);
  newMenu.append(newMenuSummary, newMenuPopover);
  newButtonGroup.append(newRowButton, newMenu);
  settings.append(newButtonGroup);

  toolbar.append(viewBar, settings);

  const renderViewContent = (query = "") => {
    const visibleRows = applyDatabaseSearch(database, viewRows, query);
    const content = activeView.type === "board"
      ? createBoardView(row, database, activeView, visibleRows, onDirty, replaceEditor)
      : activeView.type === "list"
        ? createListView(row, database, activeView, visibleRows, onDirty, replaceEditor)
        : createTableView(row, database, activeView, visibleRows, onDirty, replaceEditor);
    content.dataset.databaseContent = "true";
    return { content, visibleRows };
  };

  let { content, visibleRows } = renderViewContent();

  const footer = document.createElement("div");
  footer.className = "database-footer";
  const addRow = makeButton("database-add-row", `＋ ${t("database.newRow")}`, t("database.newRow"));
  addRow.disabled = database.rows.length >= databaseLimits.rows;
  const filtered = document.createElement("span");
  filtered.className = "database-filtered-count";
  const updateFilteredCount = () => {
    const isFiltered = visibleRows.length !== database.rows.length;
    filtered.hidden = !isFiltered;
    filtered.textContent = isFiltered
      ? t("database.filteredCount", {
          visible: formatNumber(visibleRows.length),
          total: formatNumber(database.rows.length)
        })
      : "";
  };
  footer.append(addRow, filtered);
  updateFilteredCount();

  searchInput.addEventListener("input", () => {
    const next = renderViewContent(searchInput.value);
    content.replaceWith(next.content);
    content = next.content;
    visibleRows = next.visibleRows;
    updateFilteredCount();
  });
  searchPanel.addEventListener("toggle", () => {
    if (searchPanel.open) requestAnimationFrame(() => searchInput.focus());
  });

  editor.append(heading, toolbar, content, footer);

  editor.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-action]");
    if (!button || !editor.contains(button)) return;
    const action = button.dataset.action;

    if (action === "database-select-view") {
      database.activeViewId = button.dataset.viewId;
      replaceEditor();
    } else if (action === "database-add-property") {
      if (database.properties.length >= databaseLimits.properties) return;
      const property = { id: createId("property"), name: t("database.newProperty"), type: "text", options: [] };
      database.properties.push(property);
      database.rows.forEach((dataRow) => { dataRow.values[property.id] = ""; });
      replaceEditor({ openProperties: true, focusPropertyId: property.id });
    } else if (action === "database-delete-property") {
      const property = database.properties.find((item) => item.id === button.dataset.propertyId);
      if (!property || property.type === "title" || !window.confirm(t("database.confirmDeleteProperty", { property: property.name }))) return;
      database.properties = database.properties.filter((item) => item.id !== property.id);
      database.rows.forEach((dataRow) => { delete dataRow.values[property.id]; });
      database.views.forEach((view) => {
        view.filters = view.filters.filter((filter) => filter.propertyId !== property.id);
        view.sorts = view.sorts.filter((sort) => sort.propertyId !== property.id);
        view.hiddenPropertyIds = view.hiddenPropertyIds.filter((id) => id !== property.id);
        if (view.groupPropertyId === property.id) view.groupPropertyId = null;
      });
      replaceEditor({ openProperties: true });
    } else if (action === "database-add-row") {
      if (database.rows.length >= databaseLimits.rows) return;
      const values = {};
      database.properties.forEach((property) => {
        values[property.id] = property.type === "checkbox" ? false : property.type === "number" ? null : property.type === "multi_select" ? [] : "";
      });
      const groupProperty = database.properties.find((property) => property.id === button.dataset.groupPropertyId);
      if (groupProperty?.type === "select") values[groupProperty.id] = button.dataset.groupValue ?? "";
      if (groupProperty?.type === "checkbox") values[groupProperty.id] = button.dataset.groupValue === "true";
      const dataRow = { id: createId("row"), values };
      database.rows.push(dataRow);
      replaceEditor({ focusRowId: dataRow.id });
    } else if (action === "database-delete-row") {
      if (!window.confirm(t("database.confirmDeleteRow"))) return;
      database.rows = database.rows.filter((dataRow) => dataRow.id !== button.dataset.rowId);
      replaceEditor();
    } else if (action === "database-remove-filter") {
      activeView.filters = activeView.filters.filter((filter) => filter.id !== button.dataset.filterId);
      replaceEditor({ openFilters: true });
    } else if (action === "database-remove-sort") {
      activeView.sorts = activeView.sorts.filter((sort) => sort.id !== button.dataset.sortId);
      replaceEditor({ openSorts: true });
    } else if (action === "database-delete-view") {
      if (database.views.length <= 1 || !window.confirm(t("database.confirmDeleteView", { view: activeView.name }))) return;
      const index = database.views.findIndex((view) => view.id === activeView.id);
      database.views.splice(index, 1);
      database.activeViewId = database.views[Math.max(0, index - 1)]?.id ?? database.views[0].id;
      replaceEditor();
    }
  });

  return editor;
}

export function extractDatabaseData(row) {
  return normalizeDatabaseData(row?.querySelector(".database-block-editor")?.databaseData);
}

export function summarizeDatabaseData(databaseValue) {
  const database = normalizeDatabaseData(databaseValue);
  const lines = [database.title, ...database.properties.map((property) => property.name)];
  database.rows.forEach((dataRow) => {
    database.properties.forEach((property) => {
      const value = searchableValue(property, dataRow.values[property.id]);
      if (value) lines.push(value);
    });
  });
  return lines.join("\n").slice(0, 20000);
}

